import { z } from 'zod';
import {
  hexColorSchema,
  moneySchema,
  sfSymbolSchema,
} from '../../common/schemas.js';

const accountTypeSchema = z.enum(['cash', 'card', 'bank', 'savings', 'other']);
const currencyCodeSchema = z
  .string()
  .trim()
  .length(3)
  .transform((code) => code.toUpperCase());

export const createAccountSchema = z.object({
  /** Generated by the app, so an offline create can be retried safely */
  id: z.uuid(),
  name: z.string().trim().min(1).max(64),
  type: accountTypeSchema.default('cash'),
  currency: currencyCodeSchema,
  initialBalance: moneySchema.default('0'),
  icon: sfSymbolSchema.optional(),
  color: hexColorSchema.optional(),
  includeInTotal: z.boolean().default(true),
});
export type CreateAccountInput = z.infer<typeof createAccountSchema>;

export const updateAccountSchema = z
  .object({
    name: z.string().trim().min(1).max(64),
    type: accountTypeSchema,
    currency: currencyCodeSchema,
    initialBalance: moneySchema,
    icon: sfSymbolSchema.nullable(),
    color: hexColorSchema.nullable(),
    includeInTotal: z.boolean(),
    isArchived: z.boolean(),
    /** Make this the account preselected in quick add */
    isDefault: z.literal(true),
  })
  .partial()
  .refine((patch) => Object.keys(patch).length > 0, 'Nothing to update');
export type UpdateAccountInput = z.infer<typeof updateAccountSchema>;
